import{_ as t,o,c as a,a2 as r}from"./chunks/framework.9yf7n3zg.js";const d="/guide/media/editor-window.webp",n="/guide/media/editor-zen.webp",s="/guide/media/editor-commands.webp",w=JSON.parse('{"title":"Editor","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editor.md","filePath":"guide/editor.md","lastUpdated":1792685126000}'),i={name:"guide/editor.md"};function h(c,e,l,p,u,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Editor&quot;">​</a></h1><p>The editor is where you write a story in Leathercase. It opens one story in a window of its own, as one long page of scenes, and saves each scene to a plain markdown file as you type. Nothing it writes is hidden from you: the files on disk are exactly what you typed.</p><p>You write the prose. No agent and no model ever writes, moves or renames a file of it, in the editor or anywhere else in Leathercase.</p><p><img src="'+d+'" alt="The editor on The Lamp at Ferrol: the title bar with The Lamp at Ferrol › Manuscript › The Night the Lamp Went Out and saved, the bar with scene 1 of 10 · 402 words, zen and typewriter, the Contents at the left with the three acts and their scenes, the scene&#39;s text in the middle, and the document map at the right" width="1440" height="900" loading="lazy"></p><h2 id="opening-the-editor" tabindex="-1">Opening the editor <a class="header-anchor" href="#opening-the-editor" aria-label="Permalink to &quot;Opening the editor&quot;">​</a></h2><p>Open a story, then pick <strong>Editor</strong> at the foot of the story&#39;s views in the sidebar. You can also:</p><ul><li>press <code>Ctrl+Shift+E</code> (<code>Cmd+Shift+E</code> on macOS);</li><li>pick <strong>Write the story in the editor</strong> from the story&#39;s menu (the <code>⋯</code> beside its name), or from the <strong>Story</strong> menu;</li><li>type &quot;editor&quot; in the command palette (<code>Ctrl/Cmd+K</code>).</li></ul><p>Each story has one editor window. Opening it again brings the window you already have to the front. The main window stays where it was, so you can keep the plot grid or the Graph beside the text.</p><h2 id="the-manuscript-folder" tabindex="-1">The Manuscript folder <a class="header-anchor" href="#the-manuscript-folder" aria-label="Permalink to &quot;The Manuscript folder&quot;">​</a></h2><p>A story you write in Leathercase keeps its prose in a folder inside the story&#39;s own folder, named <code>Manuscript</code>. The folder is the structure:</p><table tabindex="0"><thead><tr><th>In <code>Manuscript/</code></th><th>Is</th></tr></thead><tbody><tr><td>A folder</td><td>An act</td></tr><tr><td>A folder inside an act</td><td>A chapter</td></tr><tr><td>A markdown file</td><td>A scene</td></tr><tr><td>A <code>#</code> heading inside a scene</td><td>A section of that scene</td></tr></tbody></table><p>Order comes from the numbers at the start of the names, as <code>01 The Ledger.md</code> and <code>02 The Quay.md</code>, and numbers sort as numbers. Leathercase gives and keeps these numbers as you add scenes, chapters and acts; you never type them.</p><p>Your story&#39;s other notes (characters, places, research) stay where they are and are read as before. Only the prose lives in <code>Manuscript/</code>.</p><h3 id="importing-a-story" tabindex="-1">Importing a story <a class="header-anchor" href="#importing-a-story" aria-label="Permalink to &quot;Importing a story&quot;">​</a></h3><p>A story read from Word, Scrivener, Fountain or a folder of your own notes is read, never written. The first time you open the editor on such a story, it says so and offers <strong>Import into the Manuscript folder</strong>.</p><p>Importing copies the story&#39;s scenes as markdown into <code>Manuscript/</code>, keeping their folders, names, headings and order. A Word file becomes a markdown file; a Scrivener document comes out of its project. Your originals stay as they are: nothing is moved, changed or deleted. From then on the story is read from its <code>Manuscript/</code> copy alone, so nothing is counted twice, and the originals are no longer read.</p><p>Comments written as <code>%% … %%</code> in the originals, on one line or as a block over several, move out of the copies as they do when you type one: a short name is who speaks the line after it, anything else a comment beside the sentence before it, in the story&#39;s <code>Comments.md</code>. The originals keep theirs.</p><p>A story reads one source at a time. Importing again never writes over a scene you already have in <code>Manuscript/</code>.</p><h2 id="the-window" tabindex="-1">The window <a class="header-anchor" href="#the-window" aria-label="Permalink to &quot;The window&quot;">​</a></h2><p>The page holds every scene of the story, one after another, each under its title. Type anywhere. Markdown shows as you mean it, as Obsidian&#39;s live preview does: <code>*italics*</code> read as italics, and the marks come back while the cursor is on them.</p><p>A scene&#39;s front matter (the <code>---</code> block at the top of its file) is folded behind one faint <strong>··· properties</strong> line. Click it to show the properties; the cursor stays out of them while they are folded.</p><p>The title bar says where you are (<strong>Manuscript › The Quay</strong>) and whether the scene is <strong>saved</strong>, <strong>saving</strong> or <strong>unsaved</strong>. The bar under it says how much you wrote: <code>scene 3 of 24 · 1,208 words · 312 words this sitting</code>.</p><h3 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h3><p>Each scene is saved to its own file a moment after you stop typing. There is no Save button.</p><p>If a scene&#39;s file changes in another app while it is open here, Leathercase writes nothing over it and says: &quot;This scene changed in another app since you opened it. Nothing was written over.&quot; <strong>Keep mine</strong> writes your version; <strong>Take the other</strong> loads the file as it now is.</p><p>Closing the window, or quitting Leathercase, waits until every scene is saved. See <a href="#keeping-your-work-safe">Keeping your work safe</a>.</p><h3 id="zen-and-typewriter" tabindex="-1">Zen and typewriter <a class="header-anchor" href="#zen-and-typewriter" aria-label="Permalink to &quot;Zen and typewriter&quot;">​</a></h3><p>Two switches sit at the right of the bar under the title bar, beside the <code>⋯</code> menu:</p><ul><li><strong>Zen</strong> (<code>Ctrl+.</code>, <code>Cmd+.</code> on macOS) shows the text and the novel&#39;s name, nothing else. Move the pointer to the top right corner for its switches: zen, typewriter and full screen. <code>Esc</code> or <code>Ctrl/Cmd+.</code> leaves it.</li><li><strong>Typewriter</strong> keeps the line you are writing on a quiet band across the middle of the window. The wheel moves the text behind it.</li></ul><p><img src="'+n+'" alt="Zen on The Lamp at Ferrol: only the novel&#39;s name, faint at the top, and the scene&#39;s text" width="1440" height="900" loading="lazy"></p><h3 id="what-shows-beside-the-text" tabindex="-1">What shows beside the text <a class="header-anchor" href="#what-shows-beside-the-text" aria-label="Permalink to &quot;What shows beside the text&quot;">​</a></h3><p>The editor opens with as little as it can: the text, the Contents and the document map. The <code>⋯</code> menu turns each aid on or off, and Leathercase remembers your choice on this computer. A comment or a speaker you add turns its aid on, so what you just wrote never disappears.</p><table tabindex="0"><thead><tr><th>Aid</th><th>What it shows</th><th>At first</th></tr></thead><tbody><tr><td><strong>Names and aliases</strong></td><td>The story&#39;s names, and their other names, coloured by kind as you write them. Point at one for a card; <strong>Open beside the text</strong> shows its note</td><td>Off</td></tr><tr><td><strong>Who speaks</strong></td><td>Who says or thinks each line of dialogue</td><td>Off</td></tr><tr><td><strong>Comments beside the text</strong></td><td>Your comments, in a lane at the right, each beside its passage</td><td>Off</td></tr><tr><td><strong>Document map</strong></td><td>The whole story in miniature down the right edge; click to go there</td><td>On</td></tr><tr><td><strong>Contents</strong></td><td>The acts, chapters and scenes, at the left of the text; click to go to one</td><td>On</td></tr><tr><td><strong>Story notes panel</strong></td><td>The story&#39;s characters, places, items, factions, events and other notes, at the left, to open beside the text</td><td>Off</td></tr><tr><td><strong>Full screen</strong></td><td>The window fills the screen</td><td>Off</td></tr></tbody></table><p>A scene&#39;s title folds it: its text hides and its title says how many words it holds.</p><h3 id="moving-around" tabindex="-1">Moving around <a class="header-anchor" href="#moving-around" aria-label="Permalink to &quot;Moving around&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Alt+↓</code>, <code>Alt+↑</code></td><td>The next or the previous scene</td></tr><tr><td><code>↓</code> on a scene&#39;s last line, <code>↑</code> on its first</td><td>Into the next or the previous scene</td></tr><tr><td><code>Ctrl/Cmd+Z</code></td><td>Undo your typing in a scene</td></tr><tr><td><code>/</code></td><td>The commands, below</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>Type <code>/</code> at the start of a line or after a space to open the command box. Keep typing to narrow it, <code>↑</code> and <code>↓</code> to choose, <code>Enter</code> to run, <code>Esc</code> to close. A command never stays in your text: running it takes the typed command out.</p><p><img src="'+s+'" alt="The command box open under a slash typed after before she was awake.: Structure with /scene, /chapter, /act and /pov, then The plan with /beat, /logline and /thread, each with what it does" width="1440" height="900" loading="lazy"></p><p>The box groups them:</p><h3 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/scene</code></td><td>A new scene here. The text after the cursor goes into it. A heading right after the cursor names it; otherwise it is &quot;Untitled&quot;</td></tr><tr><td><code>/chapter</code></td><td>A new chapter after this one, with the text after the cursor</td></tr><tr><td><code>/act</code></td><td>A new act after this one, with the text after the cursor</td></tr><tr><td><code>/undo</code></td><td>Puts back the last <code>/scene</code>, <code>/chapter</code>, <code>/act</code> or rename</td></tr><tr><td><code>/pov Nora</code></td><td>Sets the scene&#39;s point of view</td></tr></tbody></table><p>Double-click a scene&#39;s, chapter&#39;s or act&#39;s title, over the text or in the Contents, to rename it. Its number stays, and Leathercase&#39;s own files follow the new name: their links to the scene, its comments, and who speaks in it.</p><p><code>/chapter</code> says so when the scenes sit directly in an act, and <code>/act</code> when the story has no acts.</p><p>After a new scene, chapter, act or rename, an <strong>Undo</strong> button shows beside the counts for a few seconds; <code>/undo</code> works for as long as the window is open, the last twenty back. An undo puts every file the command touched as it was. If you wrote in one of those scenes since, it does nothing and says so, since putting the file back would lose what you wrote; the text from before the command is in the story&#39;s history either way.</p><h3 id="the-plan" tabindex="-1">The plan <a class="header-anchor" href="#the-plan" aria-label="Permalink to &quot;The plan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/beat</code></td><td>The scene&#39;s beat, picked from the <a href="/guide/guide/beat-board">beat board</a>, or a new one typed after the command</td></tr><tr><td><code>/logline</code></td><td>Writes the scene&#39;s logline into its <a href="/guide/guide/plot-grid">plot grid</a> row: the words after the command, or the sentence before the cursor</td></tr><tr><td><code>/thread</code></td><td>Marks this passage as a stop on a <a href="/guide/guide/threads">thread</a>, picked or new</td></tr></tbody></table><h3 id="notes-beside-the-text" tabindex="-1">Notes beside the text <a class="header-anchor" href="#notes-beside-the-text" aria-label="Permalink to &quot;Notes beside the text&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/comment TYPE #tag text</code></td><td>A comment on this passage, kept beside the text, never in it. The type (<code>TODO</code>, <code>CHECK</code> or one of your own) and the tag are both optional</td></tr><tr><td><code>/todo</code>, <code>/check</code></td><td>The same as <code>/comment TODO</code> and <code>/comment CHECK</code></td></tr><tr><td><code>/who</code></td><td>Who says or thinks this line. The person who answers the last speaker comes first; <code>Tab</code> switches between says and thinks</td></tr><tr><td><code>/idea</code></td><td>Sends this line to the <a href="/guide/guide/writer-board">Writer board</a> as a card</td></tr></tbody></table><p>A comment typed in the text between <code>%%</code> marks moves beside the text once you close it. Each comment in the lane can be answered, edited, resolved, reopened, archived into <code>Comments.md</code> or deleted. See <a href="/guide/guide/comments">Comments and word lists</a>.</p><h3 id="story-notes" tabindex="-1">Story notes <a class="header-anchor" href="#story-notes" aria-label="Permalink to &quot;Story notes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/character</code>, <code>/place</code>, <code>/item</code>, <code>/event</code>, <code>/faction</code></td><td>Makes a note of that kind from the name before the cursor</td></tr><tr><td><code>/alias</code></td><td>Another name for a character: the word before the cursor</td></tr><tr><td><code>/tie</code></td><td>Draws a tie on the <a href="/guide/guide/graph">Graph</a> between two names in this paragraph</td></tr><tr><td><code>/origin 19 Leaves the farm</code></td><td>Adds an event to a character&#39;s Origin</td></tr><tr><td><code>/accent</code></td><td>A word for a character&#39;s accent, in their Voice tab</td></tr></tbody></table><p>Each of these writes through the view it belongs to, as if you had made the change there.</p><h3 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/past</code></td><td>This sentence&#39;s earlier versions, from the <a href="/guide/guide/sentence-log">sentence log</a></td></tr><tr><td><code>/echo</code></td><td>Where the word before the cursor was used before</td></tr></tbody></table><h3 id="moving" tabindex="-1">Moving <a class="header-anchor" href="#moving" aria-label="Permalink to &quot;Moving&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/go</code></td><td>Goes to a scene by its name</td></tr><tr><td><code>/open</code></td><td>Opens a note beside the text</td></tr></tbody></table><h3 id="words" tabindex="-1">Words <a class="header-anchor" href="#words" aria-label="Permalink to &quot;Words&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/th</code> (<code>/thesaurus</code>)</td><td>Other words for this one, with how they differ</td></tr><tr><td><code>/rhyme</code></td><td>Words that rhyme with it</td></tr><tr><td><code>/means</code></td><td>Words that mean what you describe</td></tr><tr><td><code>/related</code></td><td>Words that come with it</td></tr><tr><td><code>/describe</code></td><td>Adjectives this noun takes</td></tr><tr><td><code>/sounds</code></td><td>Words that sound like it</td></tr><tr><td><code>/tc</code> (<code>/transcreate</code>)</td><td>Write it in your own language, get it in the story&#39;s</td></tr></tbody></table><p>Type the word after the command, or run the command right after a word to look that word up. The box shows the words grouped, each with a note, and your sentence with the chosen word in place, so you see whether it fits. <code>Enter</code> puts it where the command was typed.</p><h2 id="what-leaves-this-computer" tabindex="-1">What leaves this computer <a class="header-anchor" href="#what-leaves-this-computer" aria-label="Permalink to &quot;What leaves this computer&quot;">​</a></h2><p>The editor goes online for one thing only: the words commands, when you run one, and only if <strong>Ask Datamuse</strong> is on in <a href="/guide/reference/settings#words">Settings › Words</a>.</p><table tabindex="0"><thead><tr><th>Who</th><th>What it receives</th><th>When</th></tr></thead><tbody><tr><td><a href="https://www.datamuse.com/api/" target="_blank" rel="noreferrer">Datamuse</a>, online</td><td>The word you look up and the words beside it, nothing more</td><td>When you run <code>/th</code>, <code>/rhyme</code>, <code>/means</code>, <code>/related</code>, <code>/describe</code> or <code>/sounds</code></td></tr><tr><td>Your local model, through Ollama</td><td>The passage around the word</td><td>When you run a words command, if you chose a model</td></tr></tbody></table><p>The local model runs on this computer, and nothing it reads leaves it. No model in the cloud is asked for words. Answers are kept in <code>words-cache.json</code> in the app&#39;s data, so the same word is instant next time.</p><p>Datamuse answers in English only. <code>/tc</code> needs a local model; without one it says where to choose one.</p><h2 id="working-offline" tabindex="-1">Working offline <a class="header-anchor" href="#working-offline" aria-label="Permalink to &quot;Working offline&quot;">​</a></h2><p>Everything in the editor works offline but the words commands. For those:</p><ul><li>With the internet, Datamuse answers.</li><li>Without it, a local model answers, if you have one: install <a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a>, then choose or download a model in <a href="/guide/reference/settings#words">Settings › Words</a>.</li><li>With neither, the box says so and points to Settings › Words.</li></ul><h2 id="writing-scenes-from-the-plot-grid-and-the-beat-board" tabindex="-1">Writing scenes from the plot grid and the beat board <a class="header-anchor" href="#writing-scenes-from-the-plot-grid-and-the-beat-board" aria-label="Permalink to &quot;Writing scenes from the plot grid and the beat board&quot;">​</a></h2><p>A scene planned on the <a href="/guide/guide/plot-grid">plot grid</a> can become a file. In a story written in Leathercase, a planned row&#39;s menu has <strong>Write the scene</strong>, and a chapter&#39;s band has <strong>Write the planned scenes</strong>. Each is written into <code>Manuscript/</code> at the grid&#39;s levels, as a heading in its chapter&#39;s file, after the scene before it, and the row is linked to it.</p><p>On the <a href="/guide/guide/beat-board">beat board</a>, a card&#39;s side column has <strong>Write the scene</strong> too: the card goes to the plot grid first if it is not there, then its row is written the same way.</p><h2 id="keeping-your-work-safe" tabindex="-1">Keeping your work safe <a class="header-anchor" href="#keeping-your-work-safe" aria-label="Permalink to &quot;Keeping your work safe&quot;">​</a></h2><p>Your prose is plain markdown files in the story&#39;s <code>Manuscript/</code> folder, and Leathercase guards them in several ways.</p><table tabindex="0"><thead><tr><th>What could go wrong</th><th>What Leathercase does</th></tr></thead><tbody><tr><td>The app or the computer stops mid-save</td><td>Each save writes a new file, puts it on the disk, then swaps it in. The scene holds its old text or its new one, never half, never an empty file</td></tr><tr><td>Another app changes a scene you have open</td><td>Nothing is written over it; you choose <strong>Keep mine</strong> or <strong>Take the other</strong></td></tr><tr><td>You close the window or quit with words not yet saved</td><td>The window waits until every scene is saved. A scene whose file changed in another app, still waiting on your choice, has what you typed kept in the story&#39;s history as <code>&lt;scene&gt; &lt;moment&gt; not saved.md</code></td></tr><tr><td>A save writes over an earlier version</td><td>The scene&#39;s text as it was goes into the story&#39;s history, at most once every ten minutes while you write, kept 30 days; the newest copy of each scene stays</td></tr><tr><td>A <code>/scene</code>, <code>/chapter</code>, <code>/act</code>, rename or undo rewrites a scene</td><td>Every text it writes over or takes away goes into the history first, however recently one was kept. The text after the cursor is written into the new scene before it leaves the old one</td></tr><tr><td>You cut a sentence you later want</td><td>The <a href="/guide/guide/sentence-log">sentence log</a> keeps every sentence you changed or cut, with what replaced it</td></tr><tr><td>You imported a story</td><td>The originals in Word, Scrivener or your own notes are never touched, so the story as it was before you wrote here is always there</td></tr></tbody></table><p>The history is the <code>.history/Manuscript/</code> folder in the story&#39;s author data folder, plain markdown files any editor opens; to go back, open one and copy what you need. See <a href="/guide/reference/suite-files#kept-versions">Kept versions</a>.</p><p>What Leathercase cannot do is keep a copy off this computer: it sends nothing anywhere. If the disk fails, the book goes with it unless your writing home is also somewhere else. Keep the home in a folder that syncs (Dropbox, iCloud Drive, OneDrive, Syncthing) or in git, or copy it to another drive now and then.</p><h2 id="not-yet" tabindex="-1">Not yet <a class="header-anchor" href="#not-yet" aria-label="Permalink to &quot;Not yet&quot;">​</a></h2><ul><li>The Graph does not write scenes: it holds the story&#39;s people, places, events and ties, not planned scenes.</li><li>The scenes the plot grid and the beat board write cannot be undone from the editor. Writing them only adds headings and files, never takes your text away; to take one back, delete it in your file manager.</li><li>Agents never write the <code>Manuscript/</code> folder. A connected agent reads it, and any change it asks for there is refused.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/manuscript">Manuscript</a>, to read the whole story as one book</li><li><a href="/guide/guide/plot-grid">Plot grid</a></li><li><a href="/guide/guide/comments">Comments and word lists</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li><li><a href="/guide/reference/settings#words">Settings › Words</a></li></ul>',80)])])}const f=t(i,[["render",h]]);export{w as __pageData,f as default};
